  if(r.statusCode<200||r.statusCode>=300){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Devir kodu oluşturulamadı.')));return;}
  if(!mounted)return;showDialog<void>(context:context,builder:(c)=>AlertDialog(backgroundColor:_panel,title:Text('Satış / Devir',style:TextStyle(color:_text)),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('Yeni araç sahibi Cepqar hesabından bu kodu girsin. QR etiketi araçta kalır ve yeni sahibine geçer.',style:TextStyle(color:_muted)),const SizedBox(height:18),SelectableText('${d['transfer_code']??''}',style:const TextStyle(color:_purple,fontSize:28,fontWeight:FontWeight.w900,letterSpacing:3)),const SizedBox(height:8),Text('Kod 24 saat geçerlidir ve tek kullanımlıktır. Devir tamamlandıktan sonra araç 90 gün boyunca tekrar devredilemez.',style:TextStyle(color:_muted))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Tamam'))]));}
Future<void> _acceptTransfer()async{final ctrl=TextEditingController();final code=await showDialog<String>(context:context,builder:(c)=>AlertDialog(backgroundColor:_panel,title:Text('Araç Devral',style:TextStyle(color:_text)),content:TextField(controller:ctrl,textCapitalization:TextCapitalization.characters,style:TextStyle(color:_text),decoration:const InputDecoration(labelText:'Devir kodu')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(c,ctrl.text.trim()),child:const Text('Devral'))]));if(code==null||code.isEmpty)return;final r=await http.post(Uri.parse('${OnboardingBackend.baseUrl}/api/owner/vehicle-transfers/accept'),headers:{'Content-Type':'application/json','x-owner-id':OnboardingDraft.userId.trim()},body:jsonEncode({'code':code}));if(r.statusCode>=200&&r.statusCode<300){await _load();widget.onVehicleChanged?.call();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Araç ve QR hesabına devredildi.')));}else if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(r.statusCode==410?'Devir kodunun süresi dolmuş.':'Araç devralınamadı.')));}
Future<void> _add()async{if(vehicles.length>=limit){_limit();return;}final x=await showDialog<_Form>(context:context,builder:(_)=>const _Dialog());if(x==null)return;try{final r=await http.post(Uri.parse('${OnboardingBackend.baseUrl}/api/owner/vehicles'),headers:{'Content-Type':'application/json','x-owner-id':OnboardingDraft.userId.trim()},body:jsonEncode({'plate':x.plate,'make':x.make,'model':x.model}));final d=r.body.isEmpty?{}:jsonDecode(r.body);if(r.statusCode==403){_limit();return;}if(r.statusCode==409&&d is Map&&d['error']=='PLATE_EXISTS')throw Exception('Bu plaka zaten kayıtlı.');if(r.statusCode<200||r.statusCode>=300)throw Exception('Araç eklenemedi.');await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}}
void _limit()=>showDialog<void>(context:context,builder:(c)=>AlertDialog(backgroundColor:_panel,title:Text(premium?'Premium araç limiti doldu':'Premium ile 3 araç ekle',style:TextStyle(color:_text,fontWeight:FontWeight.w900)),content:Text(premium?'En fazla 3 araç ekleyebilirsin.':'Standart hesapta 1, Premium ile 3 araç ekleyebilirsin.',style:TextStyle(color:_muted)),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Tamam'))]));
@override Widget build(BuildContext context){final top=MediaQuery.paddingOf(context).top;return Scaffold(backgroundColor:_bg,body:RefreshIndicator(onRefresh:_load,color:_purple,child:ListView(padding:EdgeInsets.fromLTRB(14,top+14,14,26),children:[Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Araçlarım',style:TextStyle(color:_text,fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:4),Text('Kayıtlı araçlarını yönet.',style:TextStyle(color:_muted,fontSize:13))])),FilledButton.icon(onPressed:loading?null:_add,style:FilledButton.styleFrom(backgroundColor:_purple,foregroundColor:Colors.white),icon:const Icon(Icons.add),label:const Text('Yeni Araç')),const SizedBox(width:6),IconButton(onPressed:loading?null:_acceptTransfer,tooltip:'Araç Devral',icon:const Icon(Icons.move_down_rounded,color:_purple))]),const SizedBox(height:12),Container(padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:_panel,borderRadius:BorderRadius.circular(15),border:Border.all(color:premium?_gold:_line)),child:Text(premium?'Premium • ${vehicles.length}/3 araç':'Standart • ${vehicles.length}/1 araç',style:TextStyle(color:premium?_gold:_muted,fontWeight:FontWeight.w800))),const SizedBox(height:14),if(loading)const Center(child:Padding(padding:EdgeInsets.all(36),child:CircularProgressIndicator(color:_purple)))else if(error!=null)Center(child:Text(error!,style:TextStyle(color:_muted)))else ...vehicles.map((v)=>Padding(padding:const EdgeInsets.only(bottom:12),child:_Card(v:v,selected:'${v['id']}'==selected,open:()=>_open(v),select:()=>_select(v),qr:()=>_qr(v),transfer:()=>_transfer(v),remove:()=>_remove(v)))),if(!loading&&vehicles.length<limit)OutlinedButton.icon(onPressed:_add,icon:const Icon(Icons.add_circle_outline),label:Text(premium?'Yeni araç ekle • ${limit-vehicles.length} hakkın kaldı':'Yeni araç ekle')),const SizedBox(height:16),const ActiveDriverCard(),const SizedBox(height:14),Container(padding:const EdgeInsets.all(15),d